#ifndef GENERATINGSET_H
#include "puzdef.h"
#include <set>
#include <string>
#include <vector>
using namespace std;
/*
 *   A Schreier-Sims stabilizer chain for the group generated by the moves.
 *   Sets whose pieces are all distinct and have no orientation wildcards
 *   are included, and positions are checked against the group on those.
 *   Other sets only get basic checks: within each orbit of locations under
 *   the moves, the piece counts must match the solved position, and the
 *   orientation sum must match modulo what the moves can change it by.
 *   Passing is a necessary (not sufficient) condition for a position to
 *   be solvable.
 *
 *   When it is cheap enough, the other sets go in the chain too, after the
 *   included ones, as the moves still permute their locations.  That ties
 *   them to the included sets, so their count of values can be bounded by
 *   the subgroup that leaves the included sets solved, or found exactly by
 *   walking it when it is small.
 */
struct generatingset {
  generatingset(const puzdef &pd);
  const puzdef &pd;
  allocsetval e;
  vector<vector<allocsetval>> sgs, sgsi, tk;
  vector<char> included; // per set
  // the base, as (set, location); the first nincluded are the included sets
  vector<pair<int, int>> levels;
  int nincluded;
  int slot(int L) const {
    return (pd.setdefs[levels[L].first].off >> 1) + levels[L].second;
  }
  long double levelsize(int from, int to, long double *lg = 0) const;
  // give up on putting the excluded sets in the chain past this much work
  static constexpr long long FULLCHAINBUDGET = 200000000;
  long long work;
  bool fullchain; // whether the excluded sets made it into the chain
  bool build();
  bool overbudget() const {
    return nincluded < (int)levels.size() && work > FULLCHAINBUDGET;
  }
  // walk the subgroup fixing the included sets when it is at most this big
  static constexpr long double KERNELWALKLIMIT = 1000000;
  void walkkernel(int L, const setval &p, set<string> &seen) const;
  // for excluded sets: orbit of each location, solved piece counts per
  // (orbit, piece), and per orbit the modulus of the orientation sum
  // (1 if unconstrained) and the solved orientation sum
  vector<vector<int>> orbit, solvedcnt, orimod, solvedori;
  void initbasiccheck(int i);
  bool basiccheck(const setval p) const;
  static bool eligible(const setdef &sd) { return sd.uniq && !sd.wildo; }
  bool resolve(const setval p_, int nlev);
  void showsizes() const;
  bool solvable(const setval p); // p relative to the solved position
  void knutha(int L, const setval &p);
  void knuthb(int L, const setval &p);
};
#define GENERATINGSET_H
#endif
